"""Run dog with real ptys attached to chosen fds, plus optional fake DNS server."""
import os, sys, pty, select, subprocess, threading, time, termios, tty
sys.path.insert(0, '/tmp/h')
from dnsbuild import *
from drive import serve_udp, serve_tcp

DOG = os.environ.get('DOG', '/workspace/executable')
PORT_BASE = int(os.environ.get('PORT_BASE', '5780'))
_port = [PORT_BASE + 100]

def nextport():
    _port[0] += 1
    return _port[0]

def _mkpty():
    m, s = pty.openpty()
    # disable ONLCR so \n is not translated to \r\n
    attrs = termios.tcgetattr(s)
    attrs[1] = attrs[1] & ~termios.ONLCR
    termios.tcsetattr(s, termios.TCSANOW, attrs)
    return m, s

def runpty(dogargs, respbytes=None, tty_out=True, tty_err=True, env=None,
           tcp=False, patchid=True, count=1, timeout=15, extra_env=None):
    """Returns (out_bytes, err_bytes, rc, reqs)."""
    port = None
    box = []
    th = None
    if respbytes is not None:
        port = nextport()
        def respfn(req, i):
            r = respbytes(req, i) if callable(respbytes) else respbytes
            if r is None: return None
            if patchid and len(r) >= 2:
                r = req[0:2] + r[2:]
            return r
        target = serve_tcp if tcp else serve_udp
        th = threading.Thread(target=target, args=(port, respfn, box, count), daemon=True)
        th.start()
        time.sleep(0.25)
    args = [DOG] + [a.replace('@PORT@', str(port)) for a in dogargs]
    e = dict(os.environ)
    if env is not None:
        e = dict(env)
    if extra_env:
        e.update(extra_env)

    mo = so = me = se = None
    kw = {}
    if tty_out:
        mo, so = _mkpty(); kw['stdout'] = so
    else:
        kw['stdout'] = subprocess.PIPE
    if tty_err:
        me, se = _mkpty(); kw['stderr'] = se
    else:
        kw['stderr'] = subprocess.PIPE
    kw['stdin'] = subprocess.DEVNULL

    p = subprocess.Popen(args, env=e, **kw)
    if so: os.close(so)
    if se: os.close(se)
    outbuf = bytearray(); errbuf = bytearray()
    fds = [f for f in (mo, me) if f is not None]
    deadline = time.time() + timeout
    while fds and time.time() < deadline:
        r, _, _ = select.select(fds, [], [], 0.2)
        for f in r:
            try:
                d = os.read(f, 65536)
            except OSError:
                d = b''
            if not d:
                fds.remove(f); continue
            if f == mo: outbuf += d
            else: errbuf += d
        if not r and p.poll() is not None:
            # drain
            for f in list(fds):
                try:
                    d = os.read(f, 65536)
                except OSError:
                    d = b''
                if d:
                    if f == mo: outbuf += d
                    else: errbuf += d
                else:
                    fds.remove(f)
            if not fds: break
    try:
        rc = p.wait(timeout=5)
    except subprocess.TimeoutExpired:
        p.kill(); rc = 'TIMEOUT'
    if not tty_out:
        try: outbuf += p.stdout.read()
        except Exception: pass
    if not tty_err:
        try: errbuf += p.stderr.read()
        except Exception: pass
    for f in (mo, me):
        if f is not None:
            try: os.close(f)
            except OSError: pass
    if th: th.join(0.5)
    reqs = [b for (k, b) in box if k == 'req']
    return bytes(outbuf), bytes(errbuf), rc, reqs

