import sys, os, re; sys.path.insert(0,'/tmp/h')
from probe import *
from dnsbuild import *
import struct

def levels(err):
    return re.findall(rb'\x1b\[[0-9;]*m(TRACE|DEBUG|INFO|WARN|ERROR)\x1b\[0m', err)

def lines_with(err, lvl):
    out=[]
    for ln in err.split(b'\n'):
        if lvl in ln: out.append(ln)
    return out

cases = []
good = hdr(an=1)+question('example.net',1)+rr('example.net',1,1,300,bytes([1,2,3,4]))
cases.append(('good', ['example.net','-n','127.0.0.1:@PORT@'], good, {}))
cases.append(('wrong txid', ['example.net','-n','127.0.0.1:@PORT@'], hdr(txid=0x9999)+question('example.net',1), {'patchid':False}))
cases.append(('truncated flag', ['example.net','-n','127.0.0.1:@PORT@','-U'], hdr(flags=0x8380,an=0)+question('example.net',1), {}))
cases.append(('rcode 3', ['example.net','-n','127.0.0.1:@PORT@'], hdr(flags=0x8183)+question('example.net',1), {}))
cases.append(('garbage', ['example.net','-n','127.0.0.1:@PORT@'], b'\x00\x01\x02', {'patchid':False}))
cases.append(('opt in answer', ['example.net','-n','127.0.0.1:@PORT@','--edns=show'], hdr(an=1)+question('example.net',1)+rr('.',41,4096,0,b''), {}))
cases.append(('short mode nores', ['example.net','-n','127.0.0.1:@PORT@','-1'], hdr(flags=0x8183)+question('example.net',1), {}))
cases.append(('refused conn', ['example.net','-n','127.0.0.1:9','-T'], None, {'norun':True}))

for name_, args, resp, kw in cases:
    kw = dict(kw)
    norun = kw.pop('norun', False)
    for dbg in ['trace']:
        if norun:
            import subprocess
            e2 = dict(os.environ); e2['DOG_DEBUG']=dbg
            p = subprocess.run(['/workspace/executable']+args, capture_output=True, env=e2, timeout=30)
            err = p.stderr
        else:
            o,e,rc,_ = run(args, resp, env={'DOG_DEBUG':dbg}, **kw)
            err = e
        lv = set(x.decode() for x in levels(err))
        print('== %-18s levels=%s' % (name_, sorted(lv)))
        for l in (b'WARN', b'ERROR'):
            for ln in lines_with(err, l):
                print('   %r' % ln)
